import os, pathlib, sys
target = pathlib.Path(sys.argv[1])
for p in [target, *target.parents]:
    if p.is_symlink():
        raise SystemExit("Data path must not traverse symlink: " + str(p))
    if p.exists() and not p.is_dir():
        raise SystemExit("Data path ancestor is not a directory: " + str(p))
print(next(str(p) for p in [target, *target.parents] if p.exists()))
